'use strict';

// MODULES //

var numelDimension = require( '@stdlib/ndarray/base/numel-dimension' );
var getStride = require( '@stdlib/ndarray/base/stride' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var ndarraylike2scalar = require( '@stdlib/ndarray/base/ndarraylike2scalar' );
var strided = require( '@stdlib/blas/base/dsyr' ).ndarray;


// MAIN //

/**
* Performs the symmetric rank 1 operation `A = alpha*x*x^T + A`, where `alpha` is a scalar, `x` is an `N` element ndarray, and `A` is an `N` by `N` symmetric matrix.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a two-dimensional input/output ndarray.
*     -   a zero-dimensional ndarray containing a scalar constant.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {Object} output ndarray
*
* @example
* var Float64Vector = require( '@stdlib/ndarray/vector/float64' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
* var ndarray = require( '@stdlib/ndarray/base/ctor' );
* var Float64Array = require( '@stdlib/array/float64' );
*
* var x = new Float64Vector( [ 1.0, 2.0, 3.0 ] );
* var A = new ndarray( 'float64', new Float64Array( [ 1.0, 2.0, 3.0, 2.0, 1.0, 2.0, 3.0, 2.0, 1.0 ] ), [ 3, 3 ], [ 3, 1 ], 0, 'row-major' );
*
* var alpha = scalar2ndarray( 2.0, {
*     'dtype': 'float64'
* });
*
* var out = dsyr( [ x, A, alpha ] );
* // returns <ndarray>[ [ 3.0, 6.0, 9.0 ], [ 2.0, 9.0, 14.0 ], [ 3.0, 2.0, 19.0 ] ]
*
* var bool = ( out === A );
* // returns true
*/
function dsyr( arrays ) {
	var alpha = ndarraylike2scalar( arrays[ 2 ] );
	var x = arrays[ 0 ];
	var A = arrays[ 1 ];
	strided( 'upper', numelDimension( A, 0 ), alpha, getData( x ), getStride( x, 0 ), getOffset( x ), getData( A ), getStride( A, 0 ), getStride( A, 1 ), getOffset( A ) );
	return A;
}


// EXPORTS //

module.exports = dsyr;
